ImTextureID detail_LoadTexture(int index, CreateTextureFn create)
{
    if (index < 0 || index >= 4) return 0;
    int w = 0, h = 0, n = 0;
    unsigned char* px = stbi_load_from_memory(g_textures[index].data, g_textures[index].size, &w, &h, &n, 4);
    if (!px) return 0;
    ImTextureID id = create(px, w, h);
    stbi_image_free(px);
    return id;
}

bool detail_LoadGif(int index, CreateTextureFn create, fim::GifAnim* out)
{
    if (index < 0 || index >= 0) return false;
    int* delays = nullptr;
    int w = 0, h = 0, frames = 0, comp = 0;
    unsigned char* px = stbi_load_gif_from_memory(g_gifs[index].data, g_gifs[index].size, &delays, &w, &h, &frames, &comp, 4);
    if (!px) return false;
    for (int f = 0; f < frames; f++)
    {
        out->frames.push_back(create(px + (size_t)f * w * h * 4, w, h));
        int d = delays && delays[f] > 0 ? delays[f] : 100;
        out->delays.push_back(d);
        out->totalMs += d;
    }
    out->width = w;
    out->height = h;
    stbi_image_free(px);
    if (delays) stbi_image_free(delays);
    return true;
}

ImFont* detail_LoadFont(int index, const char* fonts_dir)
{
    if (index < 0 || index >= 4) return nullptr;
    const FontBlob& f = g_fontFiles[index];
    ImFontConfig cfg;
    if (f.data)
    {
        cfg.FontDataOwnedByAtlas = false;
        return ImGui::GetIO().Fonts->AddFontFromMemoryTTF((void*)f.data, f.size, 16.0f, &cfg);
    }
    char path[1024];
    snprintf(path, sizeof(path), "%s/%s", fonts_dir ? fonts_dir : "fonts", f.file);
    return ImGui::GetIO().Fonts->AddFontFromFileTTF(path, 16.0f, &cfg);
}
